# ----------------------------------------------------------------------
# rc186 — the MCP-server CONTROL SPINE (the JSON-RPC protocol + stdio LOOP
# in C). C peers of srmech.mcp._server.MCPServer.handle / build_attestation
# + srmech.mcp._stdio.serve_stdio, so a bare-C host serves the MCP lifecycle
# + discovery (initialize / notifications/initialized / tools/list / ping /
# shutdown) natively. tools/call defers to the pure invoke_tool (rc187+ arc).
# ----------------------------------------------------------------------

# out_kind values (mirror SRMECH_MCP_* in srmech.h).
MCP_KIND_RESPONSE: int = 0
MCP_KIND_NO_RESPONSE: int = 1
MCP_KIND_DEFER_CALL: int = 2
MCP_KIND_CALL_RESULT: int = 3   # rc188 — tools/call RAN in C; buf = result text

# Parse arena for one control-message dispatch. The lifecycle/discovery
# requests (initialize / tools/list / ping / shutdown / notifications) are all
# small; tools/call is NOT routed through the C handle (the caller defers it to
# pure invoke_tool before ever calling here), so a modest bounded arena is ample.
_MCP_HANDLE_WS: int = 1 << 16


def has_native_mcp() -> bool:
    """True iff the rc186 MCP control-spine C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None and hasattr(LIB, "srmech_mcp_handle")
    )


def mcp_handle_c(request: bytes) -> "tuple[int, bytes | None] | None":
    """Dispatch one JSON-RPC ``request`` (raw bytes) through the C
    ``srmech_mcp_handle`` (default server: name ``srmech-mcp``, no filter,
    ``defer_calls=1``). Returns ``(kind, response_bytes)`` where ``kind`` is one
    of ``MCP_KIND_{RESPONSE,NO_RESPONSE,DEFER_CALL}`` and ``response_bytes`` is
    the byte-identical JSON-RPC response (or ``None`` for NO_RESPONSE /
    DEFER_CALL). Returns ``None`` when the C peer is unavailable / a non-OK
    status (the caller falls back to the pure Python dispatch).

    Two-pass (NULL-buffer size query, then fill), mirroring the tool_schema C
    projections. numpy-free."""
    if not has_native_mcp():
        return None
    ws = (ctypes.c_char * _MCP_HANDLE_WS)()
    ws_p = ctypes.cast(ws, ctypes.c_void_p)
    need = ctypes.c_size_t(0)
    kind = ctypes.c_int(-1)
    rc = LIB.srmech_mcp_handle(
        request, len(request), ws_p, _MCP_HANDLE_WS,
        None, ctypes.c_size_t(0), ctypes.byref(need), ctypes.byref(kind), 1)
    if rc != SRMECH_OK:
        return None
    if kind.value in (MCP_KIND_NO_RESPONSE, MCP_KIND_DEFER_CALL):
        return (kind.value, None)
    # RESPONSE (lifecycle/discovery JSON-RPC envelope) and CALL_RESULT (rc188 —
    # tools/call RAN in C; buf = the result TEXT the caller wraps in the content
    # + attestation envelope) both carry bytes: two-pass size-query → fill.
    size = need.value
    raw = (ctypes.c_char * size)() if size > 0 else None
    got = ctypes.c_size_t(0)
    kind2 = ctypes.c_int(-1)
    buf_p = ctypes.cast(raw, ctypes.c_void_p) if raw is not None else None
    rc = LIB.srmech_mcp_handle(
        request, len(request), ws_p, _MCP_HANDLE_WS,
        buf_p, ctypes.c_size_t(size), ctypes.byref(got), ctypes.byref(kind2), 1)
    if rc != SRMECH_OK or kind2.value not in (MCP_KIND_RESPONSE, MCP_KIND_CALL_RESULT):
        return None
    return (kind2.value, bytes(raw[:got.value]) if raw is not None else b"")


def mcp_build_attestation_c(
    tool_name: str, result_text: str, retrieved_at: str
) -> "bytes | None":
    """The MPR attestation JSON object from the C ``srmech_mcp_build_attestation``
    (``response_sha256`` over the exact preimage), byte-identical to
    ``json.dumps(build_attestation(...), separators=(",", ":"))`` for the same
    ``retrieved_at``. ``None`` if the rc186 C peer is unavailable / non-OK.

    numpy-free; two-pass (the size query needs no ws, the fill assembles the
    preimage in a caller arena sized to its exact length)."""
    if not has_native_mcp():
        return None
    tn = tool_name.encode("utf-8")
    rt = result_text.encode("utf-8")
    ra = retrieved_at.encode("utf-8")
    # size query (buf == NULL; ws not needed to size the fixed-shape object)
    need = ctypes.c_size_t(0)
    rc = LIB.srmech_mcp_build_attestation(
        tn, rt, ra, None, ctypes.c_size_t(0),
        None, ctypes.c_size_t(0), ctypes.byref(need))
    if rc != SRMECH_OK:
        return None
    # ws must hold tool \x1f "srmech <ver>" \x1f result \x1f ts; the parser
    # version ("srmech <=32 chars") + 3 separators fit comfortably in +64 slack.
    ws_len = len(tn) + len(rt) + len(ra) + 64
    ws = (ctypes.c_char * ws_len)()
    size = need.value
    raw = (ctypes.c_char * size)()
    got = ctypes.c_size_t(0)
    rc = LIB.srmech_mcp_build_attestation(
        tn, rt, ra, ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(raw, ctypes.c_void_p), ctypes.c_size_t(size),
        ctypes.byref(got))
    if rc != SRMECH_OK:
        return None
    return bytes(raw[:got.value])


# ----------------------------------------------------------------------
# rc194 — the MCP HTTP+SSE transport (the HOST-GLUE cross-terminal server in
# C). C peer of srmech.mcp._sse.serve_http_sse: a bare-C host serves MCP over
# HTTP+Server-Sent-Events on a localhost TCP port (a background accept thread
# over the rc194 TCP PAL, composing srmech_mcp_handle). Handle-based
# serve/port/stop so a Python host can drive it; the blocking serve-forever
# entry is the Python ``background=False`` native path. POSIX-first — serve
# returns non-OK on a no-TCP host and the Python pure http.server runs.
# ----------------------------------------------------------------------


def has_native_mcp_sse() -> bool:
    """True iff the rc194 MCP HTTP+SSE transport C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None and hasattr(LIB, "srmech_mcp_sse_serve")
    )


def mcp_sse_serve_c(host: str, port: int) -> "tuple[int, int] | None":
    """Start the C MCP HTTP+SSE server on ``host``:``port`` (port 0 =
    kernel-assigned). Returns ``(handle_ptr, bound_port)`` on success (the
    server runs on its own accept thread), or ``None`` when the C peer is
    unavailable / a non-OK status (POSIX-first: a no-TCP host → the caller runs
    the pure http.server). Stop it with :func:`mcp_sse_stop_c`. numpy-free."""
    if not has_native_mcp_sse():
        return None
    handle = ctypes.c_void_p()
    rc = LIB.srmech_mcp_sse_serve(
        host.encode("utf-8"), ctypes.c_uint16(port & 0xFFFF),
        ctypes.byref(handle))
    if rc != SRMECH_OK or not handle.value:
        return None
    bound = int(LIB.srmech_mcp_sse_port(handle))
    return (int(handle.value), bound)


def mcp_sse_stop_c(handle_ptr: int) -> bool:
    """Stop a running C MCP HTTP+SSE server (returned by :func:`mcp_sse_serve_c`):
    close the listener, join both threads, close all sessions, free the handle.
    No hang. Returns True on a clean stop."""
    if not has_native_mcp_sse():
        return False
    rc = LIB.srmech_mcp_sse_stop(ctypes.c_void_p(handle_ptr))
    return rc == SRMECH_OK


def mcp_serve_http_sse_c(host: str, port: int) -> int:
    """Blocking serve-forever entry (the Python ``background=False`` native
    path / a bare-C host main): serve + join the accept thread. Returns the
    srmech status (0 == clean stop; non-0 == a no-TCP host / bind error, so the
    caller falls back to the pure http.server). Blocks until the server stops."""
    if not has_native_mcp_sse():
        return SRMECH_ERR_BAD_INPUT
    return int(LIB.srmech_mcp_serve_http_sse(
        host.encode("utf-8"), ctypes.c_uint16(port & 0xFFFF)))


# ----------------------------------------------------------------------
# rc187 — the tool-call MARSHALLING FOUNDATION (the JSON-args↔typed-C-args
# value carrier). ``marshal_roundtrip_c`` drives the C round-trip prover
# (stage-1 parse → marshal_arg → serialise_result) for one argument value;
# it proves the C carrier + marshal lower a JSON arg to a typed C value that
# serialises back to the SAME canonical JSON as the pure Python
# coerce_param → serialise_native path. The carrier-typed marshal_arg /
# serialise_result are a C-only surface (rc188 invoke_tool + the C driver).
# ----------------------------------------------------------------------

# Error signals surfaced by the round-trip prover (mirror srmech.h).
MARSHAL_OK: int = 0
MARSHAL_NOT_IMPL: int = 5   # SRMECH_ERR_NOT_IMPL — not a bucket-(a) clean type
MARSHAL_BAD_INPUT: int = 2  # SRMECH_ERR_BAD_INPUT — malformed wire value


def has_native_mcp_marshal() -> bool:
    """True iff the rc187 tool-call marshalling foundation C peer is loaded."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_mcp_marshal_roundtrip")
    )


def mcp_marshal_roundtrip_c(
    type_string: str, value_json: bytes
) -> "tuple[int, bytes | None]":
    """Round-trip one MCP argument ``value_json`` (raw JSON bytes) through the C
    ``srmech_mcp_marshal_roundtrip`` for the declared ``type_string``: parse →
    stage-1 carrier → typed marshal_arg → serialise_result. Returns
    ``(status, out_bytes)`` where ``status`` is one of ``MARSHAL_OK`` /
    ``MARSHAL_NOT_IMPL`` (not a bucket-(a) clean type; caller defers to the pure
    coerce_param) / ``MARSHAL_BAD_INPUT`` (malformed wire value), and
    ``out_bytes`` is the canonical-JSON round-trip (byte-identical to the Python
    ``json.dumps(serialise_native(coerce_param(...)), separators=(",", ":"))``)
    on ``MARSHAL_OK`` else ``None``. Returns ``(-1, None)`` if the C peer is
    unavailable. numpy-free."""
    if not has_native_mcp_marshal():
        return (-1, None)
    ts = type_string.encode("utf-8")
    ws_len = 256 * len(value_json) + 65536
    ws = (ctypes.c_char * ws_len)()
    out_cap = 256 * len(value_json) + 4096
    out = (ctypes.c_char * out_cap)()
    got = ctypes.c_size_t(0)
    rc = LIB.srmech_mcp_marshal_roundtrip(
        ts, value_json, len(value_json),
        ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(out, ctypes.c_void_p), out_cap, ctypes.byref(got))
    if rc != SRMECH_OK:
        return (rc, None)
    return (MARSHAL_OK, bytes(out[:got.value]))


# ----------------------------------------------------------------------
# rc191 — the NESTED exact-ℚ carrier OPERAND marshal (the #796 linchpin
# foundation). ``carrier_marshal_roundtrip_c`` drives the C round-trip prover:
# it parses the MCP nested-ℚ wire form of a §76 telescope reducer operand (a
# Poly / BiPoly / scalar carrier), lowers it to arena-backed srmech_bigint
# coefficient arrays via srmech_carrier_read_{poly,bipoly}, and re-serialises to
# CANONICAL nested-ℚ JSON (each coefficient as [num,den] decimal). It proves the
# reader landed every (bignum) coefficient VALUE + the nesting structure —
# byte-identical to the Python carrier's own coefficient view. This is the
# reusable marshal the rc192 srmech_infer.c wiring calls to dispatch the deferred
# exact #796 infer rows (sigma-definite / q / elliptic) for a bare-C host. (NOT
# the invoke_tool vtable: the reducer kernels need MB–GB caller arenas that only
# the srmech_infer path sizes; see srmech_carrier_marshal.c.)
# ----------------------------------------------------------------------

# Carrier kinds (mirror SRMECH_CARRIER_* in srmech.h).
CARRIER_POLY: int = 0
CARRIER_BIPOLY: int = 1
CARRIER_SCALAR: int = 2
CARRIER_TRIPOLY: int = 3     # rc223: j-list of k-lists of n-coeff lists
CARRIER_QBIPOLY: int = 4     # rc223: Y-list of [x_low, [q-run, ...]] pairs
CARRIER_ELLRATIO: int = 5    # rc223: the pre-interned EllRatio wire object


def has_native_carrier_marshal() -> bool:
    """True iff the rc191 nested exact-ℚ carrier marshal C peer is loaded +
    bound. False on a no-C or pre-rc191 lib — the pure carrier coercers
    (srmech.mcp._coercion._to_poly / _to_bipoly) are the complete alternative."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_carrier_marshal_roundtrip")
    )


def carrier_marshal_roundtrip_c(
    kind: int, json_bytes: bytes
) -> "tuple[int, bytes | None]":
    """Round-trip one nested-ℚ carrier operand ``json_bytes`` (raw JSON bytes)
    of ``kind`` (``CARRIER_POLY`` / ``CARRIER_BIPOLY`` / ``CARRIER_SCALAR``)
    through the C ``srmech_carrier_marshal_roundtrip``: parse → srmech_bigint
    coefficient arrays → re-serialise canonical [num,den] JSON. Returns
    ``(status, out_bytes)`` where ``status`` is ``SRMECH_OK`` (0) on success (and
    ``out_bytes`` is the canonical round-trip) or a non-zero srmech error
    (``out_bytes`` ``None``) — a malformed operand routes the caller to the
    complete pure path. Returns ``(-1, None)`` if the C peer is unavailable.
    numpy-free."""
    if not has_native_carrier_marshal():
        return (-1, None)
    ws_len = int(LIB.srmech_carrier_marshal_arena_bytes(len(json_bytes)))
    ws = (ctypes.c_char * max(ws_len, 8))()
    out_cap = 128 * len(json_bytes) + 8192
    out = (ctypes.c_char * out_cap)()
    got = ctypes.c_size_t(0)
    rc = LIB.srmech_carrier_marshal_roundtrip(
        int(kind), json_bytes, len(json_bytes),
        ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(out, ctypes.c_void_p), out_cap, ctypes.byref(got))
    if rc != SRMECH_OK:
        return (rc, None)
    return (SRMECH_OK, bytes(out[:got.value]))


# ----------------------------------------------------------------------
# rc188 — the tools/call DISPATCH SPINE (invoke_tool). ``invoke_tool_c`` drives
# the C ``srmech_invoke_tool`` for one tool call: registry_find → per-arg
# marshal_arg → the signature-shape thunk table → serialise the result. For a
# CLEAN batch-1 c_dispatched tool it computes the result IN C and returns the
# result TEXT byte-identical to the pure ``serialise_result(invoke_tool(...))``;
# the still-wide surface (383 tools with no single C kernel, an unregistered
# name, an extra / malformed arg) DEFERS to the pure invoke_tool.
# ----------------------------------------------------------------------

# srmech_invoke_tool out_kind (mirror SRMECH_INVOKE_* in srmech.h).
INVOKE_DISPATCHED: int = 0
INVOKE_DEFER: int = 1


def has_native_invoke() -> bool:
    """True iff the rc188 tools/call invoke-spine C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_invoke_tool")
    )


def invoke_tool_c(
    name: str, arguments: "dict"
) -> "tuple[bool, str | None]":
    """Run one tool call through the C ``srmech_invoke_tool`` spine. ``name`` is
    the dotted tool name; ``arguments`` is the tools/call arguments object.

    Returns ``(dispatched, result_text)``: on a clean batch-1 dispatch
    ``(True, text)`` where ``text`` == the pure
    ``serialise_result(invoke_tool(name, arguments))`` (json.dumps default
    form); otherwise ``(False, None)`` — the caller runs the pure invoke_tool +
    attests (rc103 inform-don't-limit). Returns ``(False, None)`` when the C peer
    is unavailable. numpy-free; single-pass over a generously-sized buffer."""
    if not has_native_invoke():
        return (False, None)
    import json as _json
    nm = name.encode("utf-8")
    args_json = _json.dumps(arguments or {}, separators=(",", ":")).encode("utf-8")
    ws_len = int(LIB.srmech_invoke_tool_arena_bytes(len(args_json)))
    ws = (ctypes.c_char * ws_len)()
    out_cap = 256 * len(args_json) + 8192
    out = (ctypes.c_char * out_cap)()
    got = ctypes.c_size_t(0)
    kind = ctypes.c_int(-1)
    rc = LIB.srmech_invoke_tool(
        nm, args_json, len(args_json),
        ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(out, ctypes.c_void_p), out_cap,
        ctypes.byref(got), ctypes.byref(kind))
    if rc != SRMECH_OK or kind.value != INVOKE_DISPATCHED:
        return (False, None)
    return (True, bytes(out[:got.value]).decode("utf-8"))


# ----------------------------------------------------------------------
# rc201 (#887): the make_class OBJECT-MODEL ENGINE. ``srmech_make_class_run``
# constructs a DSL [class] instance from its packaged TOML descriptor + a
# field-state map and RUNS one declared method IN C, returning
# {"result": ..., "fields": ...} as canonical JSON (byte-identical to the pure
# CatalogClass). rc201 dispatches the One inline-constant accessors + the
# sedenion address-algebra methods (navmap/slots/is_navigable plain +
# navigate returns="self"); every other method DEFERS to pure (rc103
# inform-don't-limit). This is a private prover binding (no public callable) —
# the CatalogClass wiring + the heavy-carrier leaf batch land in rc201b/rc202.
# ----------------------------------------------------------------------

# srmech_make_class_run out_kind (mirror SRMECH_MAKE_CLASS_* in srmech.h).
MAKE_CLASS_DISPATCHED: int = 0
MAKE_CLASS_DEFER: int = 1


def has_native_make_class() -> bool:
    """True iff the rc201 make_class object-model engine C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_make_class_run")
    )


def make_class_run_c(
    class_toml: str, method: str, fields: "dict", args: "dict"
) -> "tuple[bool, str | None]":
    """Run one DSL [class] method through the C ``srmech_make_class_run`` engine.

    ``class_toml`` is the [class] descriptor TOML; ``method`` the method name;
    ``fields`` / ``args`` the instance field-state + call-args maps. Returns
    ``(dispatched, result_text)``: on a clean rc201-batch dispatch ``(True,
    text)`` where ``text`` is ``{"result": ..., "fields": ...}`` canonical JSON
    (for returns="self" "result" is the NEW instance's field DICT); otherwise
    ``(False, None)`` — the caller runs the pure CatalogClass. numpy-free."""
    if not has_native_make_class():
        return (False, None)
    import json as _json
    toml_b = class_toml.encode("utf-8")
    method_b = method.encode("utf-8")
    fields_b = _json.dumps(fields or {}, separators=(",", ":")).encode("utf-8")
    args_b = _json.dumps(args or {}, separators=(",", ":")).encode("utf-8")
    ws_len = int(LIB.srmech_make_class_run_arena_bytes(
        len(toml_b), len(fields_b), len(args_b)))
    ws = (ctypes.c_char * ws_len)()
    out_cap = 64 * (len(toml_b) + len(fields_b) + len(args_b)) + 16384
    out = (ctypes.c_char * out_cap)()
    got = ctypes.c_size_t(0)
    kind = ctypes.c_int(-1)
    rc = LIB.srmech_make_class_run(
        toml_b, len(toml_b), method_b,
        fields_b, len(fields_b), args_b, len(args_b),
        ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(out, ctypes.c_void_p), out_cap,
        ctypes.byref(got), ctypes.byref(kind))
    if rc != SRMECH_OK or kind.value != MAKE_CLASS_DISPATCHED:
        return (False, None)
    return (True, bytes(out[:got.value]).decode("utf-8"))


# ----------------------------------------------------------------------
# rc202 (#887): run_class_method -> C — the STATELESS one-shot + the FINAL owed
# orchestration row. ``srmech_run_class_method`` RESOLVES a class NAME to its
# packaged [class] descriptor (the compiled-in srmech_class_registry_table — no
# Python, no host-FS), runs one method through the rc201 engine, and WRAPS the
# result as {"class","method","result","fields"} (byte-identical to the pure
# srmech.dsl.run_class_method). An unknown / register_class_dir USER class or a
# method the engine defers DEFERS to pure (rc103 inform-don't-limit). Private
# prover binding (the pure run_class_method is the SSoT; this proves the standalone
# C capability, the rc185 pure-constructor-with-proven-equivalent-C-peer precedent).
# ----------------------------------------------------------------------


def has_native_run_class_method() -> bool:
    """True iff the rc202 run_class_method C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_run_class_method")
    )


# ----------------------------------------------------------------------
# rc359 (`#T1009`) — the CLASS-registry CONTENT surface.
#
# Carrier (`carrier_schema_json_c`) and responsion (`responsion_schema_json_c`)
# have had byte-identity ratchets since rc205 / rc225. CLASS had none: the only
# runtime check asserted that four NAMES resolve in C. A name-only assertion
# cannot see a descriptor whose BODY has drifted, which is precisely the failure
# a dotted-op-ref rename produces — C dispatches to op names that no longer
# exist while the pure path, reading the TOML off disk, keeps answering.
# ----------------------------------------------------------------------

def has_native_class_registry() -> bool:
    """True iff the rc359 class-registry ENUMERATION peers are bound."""
    return bool(
        HAS_NATIVE and LIB is not None
        and hasattr(LIB, "srmech_class_registry_count")
        and hasattr(LIB, "srmech_class_registry_get")
    )


def class_registry_count_c() -> "int | None":
    """Number of [class] descriptors compiled into the C table, or ``None``."""
    if not has_native_class_registry():
        return None
    return int(LIB.srmech_class_registry_count())


def class_registry_names_c() -> "list[str] | None":
    """Every class NAME from the C table in table order, or ``None`` if no C."""
    if not has_native_class_registry():
        return None
    n = int(LIB.srmech_class_registry_count())
    names: "list[str]" = []
    for i in range(n):
        ptr = LIB.srmech_class_registry_get(ctypes.c_size_t(i))
        if not ptr:
            return None
        names.append(ptr.contents.name.decode("utf-8"))
    return names


def class_descriptor_c(index: int) -> "dict | None":
    """The i-th descriptor as ``{"name", "toml", "toml_len"}``.

    ``toml`` is the descriptor BODY as it exists INSIDE the loaded library —
    the bytes a bare-C host actually dispatches on. Comparing it to the on-disk
    TOML is what distinguishes "the source is correct" from "the .so is
    current"; the codegen test only ever proved the former.
    """
    if not has_native_class_registry():
        return None
    ptr = LIB.srmech_class_registry_get(ctypes.c_size_t(index))
    if not ptr:
        return None
    ent = ptr.contents
    return {
        "name": ent.name.decode("utf-8"),
        "toml": ent.toml.decode("utf-8"),
        "toml_len": int(ent.toml_len),
    }


def run_class_method_c(
    class_name: str, method: str, fields: "dict", args: "dict"
) -> "tuple[bool, str | None]":
    """Resolve ``class_name`` -> its packaged descriptor + run ``method`` through
    the C ``srmech_run_class_method`` engine (NAME resolve happens IN C).

    Returns ``(dispatched, result_text)``: on a clean dispatch ``(True, text)``
    where ``text`` is ``{"class", "method", "result", "fields"}`` canonical JSON
    (byte-identical to json.dumps of the pure run_class_method dict); otherwise
    ``(False, None)`` — the caller runs the pure run_class_method (an unknown /
    user class, or a leaf the engine defers). numpy-free."""
    if not has_native_run_class_method():
        return (False, None)
    import json as _json
    name_b = class_name.encode("utf-8")
    method_b = method.encode("utf-8")
    fields_b = _json.dumps(fields or {}, separators=(",", ":")).encode("utf-8")
    args_b = _json.dumps(args or {}, separators=(",", ":")).encode("utf-8")
    ws_len = int(LIB.srmech_run_class_method_arena_bytes(
        name_b, len(fields_b), len(args_b)))
    ws = (ctypes.c_char * ws_len)()
    out_cap = 64 * (len(name_b) + len(method_b) + len(fields_b) + len(args_b)) + 16384
    out = (ctypes.c_char * out_cap)()
    got = ctypes.c_size_t(0)
    kind = ctypes.c_int(-1)
    rc = LIB.srmech_run_class_method(
        name_b, method_b, fields_b, len(fields_b), args_b, len(args_b),
        ctypes.cast(ws, ctypes.c_void_p), ws_len,
        ctypes.cast(out, ctypes.c_void_p), out_cap,
        ctypes.byref(got), ctypes.byref(kind))
    if rc != SRMECH_OK or kind.value != MAKE_CLASS_DISPATCHED:
        return (False, None)
    return (True, bytes(out[:got.value]).decode("utf-8"))


# ----------------------------------------------------------------------
# rc193 (HOST-GLUE): the CLI arg-GRAMMAR + dispatch. ``srmech.cli.main.main``
# runs the argv through the C ``srmech_cli_parse`` (the grammar for all five
# subcommands) + ``srmech_cli_dispatch`` (the run-body routing) on the clean
# RUN path, deferring help/version/errors + anything the bounded parser will
# not risk to pure argparse (byte-identical, inform-don't-limit).
# ----------------------------------------------------------------------

# srmech_cli_parse out_action (mirror SRMECH_CLI_ACTION_* in srmech.h).
CLI_ACTION_RUN: int = 0
CLI_ACTION_HELP: int = 1
CLI_ACTION_VERSION: int = 2
CLI_ACTION_ERROR: int = 3

# srmech_cli_dispatch out_route (mirror SRMECH_CLI_ROUTE_* in srmech.h).
CLI_ROUTE_STATUS: int = 0
CLI_ROUTE_BUS: int = 1
CLI_ROUTE_DSL: int = 2
CLI_ROUTE_MCP: int = 3
CLI_ROUTE_CLASS: int = 4
CLI_ROUTE_HELP: int = 5


def has_native_cli() -> bool:
    """True iff the rc193 CLI grammar + dispatch C peer is loaded + bound."""
    return bool(
        HAS_NATIVE and LIB is not None and hasattr(LIB, "srmech_cli_parse")
    )


def cli_parse_c(argv: "list[str]") -> "tuple[int, bytes] | None":
    """Parse ``argv`` (the console-script arguments, prog EXCLUDED) through the
    C ``srmech_cli_parse``. Returns ``(action, namespace_json)`` where ``action``
    is one of ``CLI_ACTION_{RUN,HELP,VERSION,ERROR}`` and ``namespace_json`` is
    the canonical parsed-namespace JSON (empty for non-RUN actions). Returns
    ``None`` when the C peer is unavailable OR the bounded parser DEFERS
    (``SRMECH_ERR_NOT_IMPL`` / overflow) — the caller runs pure argparse.
    numpy-free; single-pass over a generously-sized buffer."""
    if not has_native_cli():
        return None
    n = len(argv)
    arr = (ctypes.c_char_p * (n if n > 0 else 1))()
    for i, a in enumerate(argv):
        arr[i] = a.encode("utf-8")
    out_cap = 1 << 16
    out = ctypes.create_string_buffer(out_cap)
    got = ctypes.c_size_t(0)
    action = ctypes.c_int(-1)
    exit_code = ctypes.c_int(-1)
    argv_p = ctypes.cast(arr, ctypes.POINTER(ctypes.c_char_p)) if n > 0 else None
    rc = LIB.srmech_cli_parse(
        n, argv_p, out, out_cap,
        ctypes.byref(got), ctypes.byref(action), ctypes.byref(exit_code))
    if rc != SRMECH_OK:
        return None
    if action.value == CLI_ACTION_RUN:
        return (CLI_ACTION_RUN, bytes(out.raw[: got.value]))
    return (action.value, b"")


def cli_dispatch_c(namespace_json: bytes) -> "int | None":
    """Route a parsed-namespace JSON (from :func:`cli_parse_c` on ACTION_RUN)
    to its run-body target via the C ``srmech_cli_dispatch``. Returns one of
    ``CLI_ROUTE_{STATUS,BUS,DSL,MCP,CLASS,HELP}``, or ``None`` when the C peer is
    unavailable / the JSON carries no recognizable command."""
    if not has_native_cli():
        return None
    route = ctypes.c_int(-1)
    rc = LIB.srmech_cli_dispatch(
        namespace_json, len(namespace_json), ctypes.byref(route))
    if rc != SRMECH_OK:
        return None
    return route.value


def sha256_hex_c(data: bytes) -> str:
    """Native SHA-256 — must only be called when HAS_NATIVE is True.

    Byte-exact with hashlib.sha256(data).hexdigest(). Empty bytes
    are valid (mirrors hashlib semantics).
    """
    if not HAS_NATIVE or LIB is None:
        raise RuntimeError(
            "srmech._native.sha256_hex_c called but HAS_NATIVE is False; "
            "use srmech.amsc.format.sha256_bytes (which dispatches correctly)"
        )
    out = ctypes.create_string_buffer(65)  # 64 hex chars + NUL
    # Empty bytes: pass a NULL pointer + 0 length, which the C side
    # tolerates (special-cased in srmech_sha256_hex).
    if len(data) == 0:
        rc = LIB.srmech_sha256_hex(
            ctypes.cast(None, ctypes.POINTER(ctypes.c_uint8)),
            ctypes.c_size_t(0),
            out,
        )
    else:
        buf = (ctypes.c_uint8 * len(data)).from_buffer_copy(data)
        rc = LIB.srmech_sha256_hex(buf, ctypes.c_size_t(len(data)), out)
    if rc != SRMECH_OK:
        raise RuntimeError(
            f"srmech_sha256_hex returned non-OK status {rc}; "
            f"this should not happen for valid inputs"
        )
    return out.value.decode("ascii")


# ----------------------------------------------------------------------
# rc178 (ANNEX Batch A): RFC 2104 HMAC-SHA-256 + the bus Bio-TOTP wire
# cipher. ``srmech.bus._bio_totp`` dispatches ``derive_key`` /
# ``_stream_cipher`` (default HMAC-CTR path) / ``decode_splice`` through
# these when ``has_native_bio_totp()``; each keeps the COMPLETE pure path
# for a stale / no-C host. Byte-exact mirrors — parity IS the safety
# property (a deviation would silently break the wire cipher).
# ----------------------------------------------------------------------

def has_native_bio_totp() -> bool:
    """True iff the rc178 Bio-TOTP cipher C peer is loaded + bound."""
    return bool(
        HAS_NATIVE
        and LIB is not None
        and hasattr(LIB, "srmech_hmac_sha256")
        and hasattr(LIB, "srmech_bio_totp_derive_key")
        and hasattr(LIB, "srmech_bio_totp_keystream_xor")
        and hasattr(LIB, "srmech_bio_totp_decode_splice")
    )


def _u8_ptr(data: bytes):
    """A ``POINTER(c_uint8)`` over a fresh copy of ``data`` (or NULL for
    empty), for a read-only C argument."""
    if len(data) == 0:
        return ctypes.cast(None, ctypes.POINTER(ctypes.c_uint8))
    return (ctypes.c_uint8 * len(data)).from_buffer_copy(data)


def hmac_sha256_c(key: bytes, msg: bytes) -> bytes:
    """Native RFC 2104 HMAC-SHA-256 — RAW 32-byte MAC. Byte-exact with
    ``hmac.new(key, msg, "sha256").digest()``. Requires the rc178 symbol."""
    if not (HAS_NATIVE and LIB is not None
            and hasattr(LIB, "srmech_hmac_sha256")):
        raise RuntimeError(
            "srmech_hmac_sha256 unavailable; use hmac.new(key, msg, 'sha256')"
        )
    out = (ctypes.c_uint8 * 32)()
    rc = LIB.srmech_hmac_sha256(
        _u8_ptr(bytes(key)), ctypes.c_size_t(len(key)),
        _u8_ptr(bytes(msg)), ctypes.c_size_t(len(msg)),
        out,
    )
    if rc != SRMECH_OK:
        raise RuntimeError(f"srmech_hmac_sha256 returned non-OK status {rc}")
    return bytes(out)


def bio_totp_derive_key_c(dna: bytes, time_ns: int, window_ns: int) -> bytes:
    """Native Bio-TOTP key derive — 16 bytes. Byte-exact with
    ``srmech.bus._bio_totp.derive_key``. Returns ``None`` on OVERFLOW
    (dna longer than the native cap) so the caller runs the pure path."""
    out = (ctypes.c_uint8 * 16)()
    rc = LIB.srmech_bio_totp_derive_key(
        _u8_ptr(bytes(dna)), ctypes.c_size_t(len(dna)),
        ctypes.c_int64(int(time_ns)), ctypes.c_int64(int(window_ns)),
        out,
    )
    if rc != SRMECH_OK:
        return None
    return bytes(out)


def bio_totp_keystream_xor_c(key16: bytes, nonce16: bytes,
                             data: bytes) -> bytes:
    """Native Bio-TOTP HMAC-CTR keystream XOR (encrypt == decrypt).
    Byte-exact with the stdlib branch of ``_bio_totp._stream_cipher``."""
    n = len(data)
    if n == 0:
        return b""
    out = (ctypes.c_uint8 * n)()
    rc = LIB.srmech_bio_totp_keystream_xor(
        _u8_ptr(bytes(key16)), _u8_ptr(bytes(nonce16)),
        _u8_ptr(bytes(data)), ctypes.c_size_t(n), out,
    )
    if rc != SRMECH_OK:
        return None
    return bytes(out)


def bio_totp_decode_splice_c(framed: bytes, dna: bytes,
                             window_ns: int, now_ns: int):
    """Native Bio-TOTP ``decode_splice``. Returns ``(plaintext, used_time)``
    on success, the sentinel ``False`` when the native op ran but no window
    bound (the caller raises BioTotpDecryptError), or ``None`` to fall to the
    pure path (non-OK status / short frame). Byte-exact with the pure
    ``decode_splice`` verdict + plaintext."""
    body = bytes(framed)
    if len(body) < 16:
        return None                     # format error — caller handles
    ct_len = len(body) - 16
    ws_bytes = int(LIB.srmech_bio_totp_decode_splice_arena_bytes(
        ctypes.c_size_t(len(body))))
    ws = (ctypes.c_char * ws_bytes)()
    out_pt = (ctypes.c_uint8 * (ct_len if ct_len > 0 else 1))()
    out_len = ctypes.c_size_t(0)
    out_used = ctypes.c_int64(0)
    out_found = ctypes.c_int(0)
    rc = LIB.srmech_bio_totp_decode_splice(
        _u8_ptr(body), ctypes.c_size_t(len(body)),
        _u8_ptr(bytes(dna)), ctypes.c_size_t(len(dna)),
        ctypes.c_int64(int(window_ns)), ctypes.c_int64(int(now_ns)),
        ws, ctypes.c_size_t(ws_bytes),
        out_pt, ctypes.c_size_t(ct_len),
        ctypes.byref(out_len), ctypes.byref(out_used), ctypes.byref(out_found),
    )
    if rc != SRMECH_OK:
        return None
    if not out_found.value:
        return False
    return bytes(out_pt[:out_len.value]), int(out_used.value)


# ----------------------------------------------------------------------
# v0.7.5rc2: scalar transcendental cascade wrappers — the Python-callable
# face of the rc43-46 C cascade. The float-projection ops in
# ``srmech.math.rational`` dispatch through these when ``has_native_trig()``.
# ----------------------------------------------------------------------

def has_native_trig() -> bool:
    """True iff the C transcendental cascade is loaded + bound (rc43+ lib)."""
    return bool(HAS_NATIVE and LIB is not None and hasattr(LIB, "srmech_sin"))


def has_native_explog() -> bool:
    """True iff the C exp/log cascade is loaded + bound (rc46+ lib)."""
    return bool(HAS_NATIVE and LIB is not None and hasattr(LIB, "srmech_exp"))


def has_native_sqrt() -> bool:
    """True iff the C integer-isqrt sqrt cascade is loaded + bound (rc45+ lib)."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_rational_sqrt"))


def has_native_pi_chudnovsky() -> bool:
    """True iff the rotation-last Chudnovsky π C symbols are loaded + bound
    (0.9.0rc19+ lib): :func:`srmech.math.rational.pi_chudnovsky_digits`
    dispatches to the exact-bigint native path. False on a no-C or pre-rc19
    lib — the pure-Python int-bignum body is the complete alternative (and the
    parity oracle); the two paths emit byte-identical ``"3.<digits>"``."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_pi_chudnovsky")
                and hasattr(LIB, "srmech_pi_chudnovsky_ws_bound"))


def pi_chudnovsky_c(num_digits: int) -> "str | None":
    """Native rotation-last Chudnovsky π → ``"3.<num_digits digits>"`` or None.

    Returns ``None`` when the native symbols are absent (no-C / pre-rc19 lib)
    so the caller falls through to the pure-Python bignum body. Sizes the
    caller arena via ``srmech_pi_chudnovsky_ws_bound``, then calls the exact
    C path; a non-OK status raises :class:`RuntimeError`. Byte-identical to the
    pure-Python oracle (proven C==Python==Archimedes at 1000 + 10000 digits)."""
    if not has_native_pi_chudnovsky():
        return None
    ws_len = int(LIB.srmech_pi_chudnovsky_ws_bound(ctypes.c_uint32(num_digits)))
    ws = (ctypes.c_uint8 * max(ws_len, 1))()
    out_cap = num_digits + 8                      # "3." + digits + NUL + slack
    out = (ctypes.c_char * out_cap)()
    out_len = ctypes.c_size_t(0)
    rc = LIB.srmech_pi_chudnovsky(
        ctypes.c_uint32(num_digits),
        out,
        ctypes.c_size_t(out_cap),
        ctypes.byref(out_len),
        ctypes.cast(ws, ctypes.c_void_p),
        ctypes.c_size_t(ws_len),
    )
    if rc != SRMECH_OK:
        raise RuntimeError(
            f"srmech_pi_chudnovsky returned non-OK status {rc}"
        )
    return bytes(out)[:out_len.value].decode("ascii")


def has_native_pi_archimedes() -> bool:
    """True iff the projects-every-step Pfaff-Archimedes π C symbol is loaded +
    bound (0.9.0rc157+ lib): :func:`srmech.math.rational.pi_cascade_digits`
    dispatches to the WHOLE two-mean chiral-pair loop in C. False on a no-C or
    pre-rc157 lib — the pure-Python fixed-point body is the complete alternative
    (and the parity oracle); the two paths emit byte-identical ``"3.<digits>"``."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_pi_archimedes"))


def pi_archimedes_c(num_digits: int, max_cascade_depth: int,
                    precision_bits: int) -> "str | None":
    """Native Pfaff-Archimedes π → ``"3.<num_digits digits>"`` or None.

    Runs the WHOLE chiral-pair cascade (per-step harmonic-mean ``divmod`` +
    geometric-mean ``isqrt`` over the caller-arena ``srmech_bigint``) in C, so a
    bare-C host reaches the digit stream with no Python and no O(digits²) per-
    step decimal round-trip. Returns ``None`` when the native symbol is absent
    (no-C / pre-rc157 lib) so the caller falls through to the pure-Python fixed-
    point body. Byte-identical to that oracle (same integers, same Python-FLOOR
    semantics, same ``max_cascade_depth`` / ``precision_bits``). A non-OK C
    status raises :class:`RuntimeError`.

    The arena is sized generously in Python (like ``bigint_isqrt_c``): the
    largest carrier is 12·M² (~2·M limbs) with M = 2^``precision_bits``, plus the
    10^``num_digits`` read-out limbs; too-small → ``SRMECH_ERR_OVERFLOW`` → the
    complete pure fallback (never a wrong answer)."""
    if not has_native_pi_archimedes():
        return None
    assert num_digits > 0, "pi_archimedes_c requires num_digits > 0"
    assert max_cascade_depth > 0 and precision_bits > 0, "depth/precision > 0"
    # Per-carrier limb cap + 9 carriers + divmod/isqrt scratch (mirrors the C
    # arch_carrier_limbs layout; over-sizing the bump arena is free).
    m_limbs = precision_bits // 32 + 2
    d_limbs = num_digits // 9 + 2
    cap = 2 * m_limbs + d_limbs + 32
    ws_words = cap * 9 + 24 * m_limbs + 8 * d_limbs + 512
    ws = (ctypes.c_uint8 * (ws_words * 4))()
    out_cap = num_digits + 8                       # "3." + digits + NUL + slack
    out = (ctypes.c_char * out_cap)()
    out_len = ctypes.c_size_t(0)
    rc = LIB.srmech_pi_archimedes(
        ctypes.c_uint32(num_digits),
        ctypes.c_uint32(max_cascade_depth),
        ctypes.c_uint32(precision_bits),
        out,
        ctypes.c_size_t(out_cap),
        ctypes.byref(out_len),
        ctypes.cast(ws, ctypes.c_void_p),
        ctypes.c_size_t(ws_words * 4),
    )
    if rc != SRMECH_OK:
        raise RuntimeError(
            f"srmech_pi_archimedes returned non-OK status {rc}"
        )
    return bytes(out)[:out_len.value].decode("ascii")


# ----------------------------------------------------------------------
# Cayley-Dickson loop NAVIGATION (v0.9.0rc158; Qalg TAIL Batch 2) — the INTEGER
# combinatorial layer over srmech_cd_basis_product. Signed basis units
# (sign, index); no bignum, no float. A bare-C host navigates the CD loop with
# no Python via these four symbols. Each *_c helper returns None on a no-C /
# pre-rc158 lib (or a bounded-search overflow) so the caller falls through to
# the complete pure-Python oracle — the byte-identical parity twin.
# ----------------------------------------------------------------------

def has_native_cd_closure() -> bool:
    """True iff the CD loop-navigation C symbols (rc158+) are loaded + bound."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_cd_closure")
                and hasattr(LIB, "srmech_cd_left_orbit")
                and hasattr(LIB, "srmech_cd_min_generating_set"))
    # (rc395, `#T1000`) srmech_cd_zero_divisor_witness dropped from this gate —
    # the symbol was removed (ABI 10 -> 11); the three surviving nav symbols are
    # the only ones cd_closure_c / cd_left_orbit_c / cd_min_generating_set_c use.


def cd_closure_c(dim: int, gen_idxs: "list[int]") -> "set | None":
    """Native sub-loop closure → a ``set`` of ``(sign, index)`` signed units, or
    None (no-C lib). The C fixpoint composes ``srmech_cd_basis_product``; the set
    it returns is element-identical to the pure-Python ``closure`` oracle."""
    if not has_native_cd_closure():
        return None
    n = len(gen_idxs)
    gens = (ctypes.c_int * n)(*gen_idxs) if n else (ctypes.c_int * 0)()
    cap = 2 * dim
    signs = (ctypes.c_int * cap)()
    idxs = (ctypes.c_int * cap)()
    count = ctypes.c_size_t(0)
    rc = LIB.srmech_cd_closure(
        int(dim), gens, ctypes.c_size_t(n), signs, idxs,
        ctypes.c_size_t(cap), ctypes.byref(count))
    if rc != SRMECH_OK:
        return None
    return {(int(signs[i]), int(idxs[i])) for i in range(count.value)}


def cd_left_orbit_c(dim: int, start_idx: int, gen_idx: int) -> "list | None":
    """Native left-multiplication orbit → a ``list`` of ``(sign, index)`` in
    cycle order, or None (no-C lib). Byte-identical (same walk order) to the
    pure-Python ``left_orbit`` oracle."""
    if not has_native_cd_closure():
        return None
    cap = 2 * dim
    signs = (ctypes.c_int * cap)()
    idxs = (ctypes.c_int * cap)()
    count = ctypes.c_size_t(0)
    rc = LIB.srmech_cd_left_orbit(
        int(dim), int(start_idx), int(gen_idx), signs, idxs,
        ctypes.c_size_t(cap), ctypes.byref(count))
    if rc != SRMECH_OK:
        return None
    return [(int(signs[i]), int(idxs[i])) for i in range(count.value)]


def cd_min_generating_set_c(dim: int, units: "list[int]") -> "int | None":
    """Native minimum spanning cardinality: ``k > 0`` (a k-subset spans), ``0``
    (NO subset spans → the caller raises ValueError), or None (no-C lib OR the
    bounded combinatorial search overflowed → the caller uses the pure oracle).
    Composes ``srmech_cd_closure`` over each combination."""
    if not has_native_cd_closure():
        return None
    n = len(units)
    arr = (ctypes.c_int * n)(*units) if n else (ctypes.c_int * 0)()
    out_k = ctypes.c_int(-1)
    rc = LIB.srmech_cd_min_generating_set(
        int(dim), arr, ctypes.c_size_t(n), ctypes.byref(out_k))
    if rc != SRMECH_OK:                     # OVERFLOW / bad-input → pure oracle
        return None
    return int(out_k.value)


# (rc395, `#T1000`) cd_zero_divisor_witness_c() REMOVED — the dedicated dim-16
# brute-force C export srmech_cd_zero_divisor_witness is gone (ABI 10 -> 11).
# Its dim-general successors cd_zero_divisor_witness / cd_zero_divisor_witnesses
# are composition_of_c over the already-dispatched gf_rref + cd_basis_product, so
# no whole-op native wrapper is needed.


# ----------------------------------------------------------------------
# Cayley-Dickson EXACT-ℚ VECTOR carrier dispatch (v0.9.0rc159; Qalg TAIL
# Batch 3). A CD element of dim 2^k is a ℚ-vector of `dim` (num, den)
# components; the four kernels back cayley_dickson.{cd_basis, cd_conjugate,
# cd_add, cd_norm_sq}. They REUSE the C-side qmat exact-ℚ scalar machinery
# (the 1-D sibling of srmech_qmat) and the poly num/den array marshalers
# (_poly_make_array / _poly_blank_array / _poly_read_array — the same
# decimal-bridge pattern; resolved at call time). BYTE-IDENTICAL to Python's
# Fraction (num, den) at any magnitude; None on a no-C / pre-rc159 lib → the
# caller uses the pure-Fraction oracle.
# ----------------------------------------------------------------------

_CD_QVEC_SYMS = (
    "srmech_cd_qbasis",
    "srmech_cd_qconjugate",
    "srmech_cd_qadd",
    "srmech_cd_qnorm_sq",
    "srmech_cd_qvec_ws_bound",
    "srmech_cd_qvec_entry_cap",
    "srmech_bigint_from_dec",
    "srmech_bigint_to_dec",
    "srmech_bigint_to_dec_bound",
)


def has_native_cd_qvec() -> bool:
    """True iff the rc159 CD exact-ℚ vector kernels + the srmech_bigint
    decimal-marshal helpers are loaded + bound. False on a no-C or pre-rc159
    lib — the pure-Python Fraction body in
    ``srmech.cascade.cayley_dickson`` is the complete alternative (and the
    parity oracle); both emit byte-identical exact (num, den)."""
    if not (HAS_NATIVE and LIB is not None):
        return False
    return all(hasattr(LIB, s) for s in _CD_QVEC_SYMS)


def cd_qbasis_c(dim: int, i: int) -> "list | None":
    """Native unit basis vector e_i → list of ``dim`` reduced ``(num, den)``
    tuples ([(0,1), …, (1,1) at i, …]), or None (no-C lib). No ℚ arithmetic —
    a Class-A basis convention, so the tiny 2-limb carriers suffice."""
    if not has_native_cd_qvec():
        return None
    o_n, o_d, ko = _poly_blank_array(dim, 2)          # 0/1 or 1/1 fit in 1 limb
    rc = LIB.srmech_cd_qbasis(int(dim), int(i), o_n, o_d)
    _ = ko
    if rc != SRMECH_OK:
        return None
    return _poly_read_array(o_n, o_d, dim)


def cd_qconjugate_c(components) -> "list | None":
    """Native CD conjugation → list of ``dim`` reduced ``(num, den)`` tuples
    (imaginary components 1..dim-1 negated, component 0 kept), or None (no-C
    lib). ``components`` is a ``(num, den)`` sequence."""
    if not has_native_cd_qvec():
        return None
    dim = len(components)
    out_cap = _poly_coeff_limbs(components) + 2       # copy + Class-K sign flip
    x_n, x_d, kx = _poly_make_array(components, out_cap)
    o_n, o_d, ko = _poly_blank_array(dim, out_cap)
    rc = LIB.srmech_cd_qconjugate(x_n, x_d, int(dim), o_n, o_d)
    _ = (kx, ko)
    if rc != SRMECH_OK:
        return None
    return _poly_read_array(o_n, o_d, dim)


def cd_qadd_c(x_components, y_components) -> "list | None":
    """Native component-wise exact-ℚ sum → list of ``dim`` reduced ``(num,
    den)`` tuples, or None (no-C lib). Both are same-length ``(num, den)``
    sequences. The out entry cap + caller arena are sized from the input limb
    count via the C sizing symbols (generous; a too-small arena → OVERFLOW →
    None → the caller's pure oracle)."""
    if not has_native_cd_qvec():
        return None
    dim = len(x_components)
    cl = max(_poly_coeff_limbs(x_components), _poly_coeff_limbs(y_components))
    out_cap = int(LIB.srmech_cd_qvec_entry_cap(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws_len = int(LIB.srmech_cd_qvec_ws_bound(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws = (ctypes.c_uint8 * max(ws_len, 8))()
    x_n, x_d, kx = _poly_make_array(x_components, out_cap)
    y_n, y_d, ky = _poly_make_array(y_components, out_cap)
    o_n, o_d, ko = _poly_blank_array(dim, out_cap)
    rc = LIB.srmech_cd_qadd(
        x_n, x_d, y_n, y_d, int(dim), o_n, o_d,
        ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len))
    _ = (kx, ky, ko)
    if rc != SRMECH_OK:
        return None
    return _poly_read_array(o_n, o_d, dim)


def cd_qnorm_sq_c(components) -> "tuple | None":
    """Native squared norm Σ x_i² → one reduced ``(num, den)`` tuple, or None
    (no-C lib). ``components`` is a ``(num, den)`` sequence."""
    if not has_native_cd_qvec():
        return None
    dim = len(components)
    cl = _poly_coeff_limbs(components)
    out_cap = int(LIB.srmech_cd_qvec_entry_cap(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws_len = int(LIB.srmech_cd_qvec_ws_bound(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws = (ctypes.c_uint8 * max(ws_len, 8))()
    x_n, x_d, kx = _poly_make_array(components, out_cap)
    o_num, kon = _bigint_from_int(0, out_cap)
    o_den, kod = _bigint_from_int(1, out_cap)
    rc = LIB.srmech_cd_qnorm_sq(
        x_n, x_d, int(dim), ctypes.byref(o_num), ctypes.byref(o_den),
        ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len))
    _ = (kx, kon, kod)
    if rc != SRMECH_OK:
        return None
    return (_bigint_to_int(o_num), _bigint_to_int(o_den))


def has_native_cd_mult() -> bool:
    """True iff the rc160 CD exact-ℚ PRODUCT kernel is loaded (plus the Qvec
    sizing + srmech_bigint decimal-marshal helpers it shares). False on a no-C
    or pre-rc160 lib — the pure-Python recursive ``_mult`` in
    ``srmech.cascade.cayley_dickson`` is the complete, byte-identical
    alternative (and the parity oracle)."""
    return has_native_cd_qvec() and (
        LIB is not None and hasattr(LIB, "srmech_cd_mult"))


def cd_mult_c(x_components, y_components) -> "list | None":
    """Native arbitrary-rational Cayley–Dickson product x·y → list of ``dim``
    reduced ``(num, den)`` tuples, or None (no-C / pre-rc160 lib). Both are
    same-length ``(num, den)`` sequences. Sized from the input limb count via
    the shared Qvec sizing symbols (each output slot sums ``dim`` products — the
    same accumulation profile as cd_norm_sq); a too-small arena → OVERFLOW →
    None → the caller's pure-Fraction oracle."""
    if not has_native_cd_mult():
        return None
    dim = len(x_components)
    if dim != len(y_components):
        return None
    cl = max(_poly_coeff_limbs(x_components), _poly_coeff_limbs(y_components))
    out_cap = int(LIB.srmech_cd_qvec_entry_cap(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws_len = int(LIB.srmech_cd_qvec_ws_bound(
        ctypes.c_size_t(cl), ctypes.c_size_t(dim)))
    ws = (ctypes.c_uint8 * max(ws_len, 8))()
    x_n, x_d, kx = _poly_make_array(x_components, out_cap)
    y_n, y_d, ky = _poly_make_array(y_components, out_cap)
    o_n, o_d, ko = _poly_blank_array(dim, out_cap)
    rc = LIB.srmech_cd_mult(
        x_n, x_d, y_n, y_d, int(dim), o_n, o_d,
        ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len))
    _ = (kx, ky, ko)
    if rc != SRMECH_OK:
        return None
    return _poly_read_array(o_n, o_d, dim)


def algebra_table_c(dim: int, gammas) -> "list | None":
    """Native gamma-parameterised Cayley–Dickson structure-constant table →
    the flat ``dim³`` list of ``int`` coefficients (row-major
    ``table[(i*dim + j)*dim + k]``), or None (no-C / pre-rc352 lib).

    ``gammas`` is the per-doubling γ in LADDER order (``gammas[0]`` is ℝ→ℂ) or
    None for the definite ladder. Integer-only — no arena, no bignum: the
    cocycle underneath IS ``srmech_cd_basis_product``'s, generalised."""
    if not (HAS_NATIVE and LIB is not None
            and hasattr(LIB, "srmech_algebra_table")):
        return None
    n = int(dim) ** 3
    out = (ctypes.c_int64 * n)()
    if gammas is None:
        gbuf = None
        n_g = 0
    else:
        n_g = len(gammas)
        gbuf = (ctypes.c_int * max(n_g, 1))(*[int(g) for g in gammas])
    rc = LIB.srmech_algebra_table(
        int(dim),
        ctypes.cast(gbuf, ctypes.POINTER(ctypes.c_int)) if gbuf is not None
        else ctypes.cast(None, ctypes.POINTER(ctypes.c_int)),
        ctypes.c_size_t(n_g), out)
    if rc != SRMECH_OK:
        return None
    return [int(out[i]) for i in range(n)]


def has_native_algebra_table_product() -> bool:
    """True iff the rc352 TABLE-DRIVEN exact-ℚ product kernel is loaded (plus
    the srmech_bigint decimal-marshal helpers it shares with cd_mult). False on
    a no-C or pre-rc352 lib — the pure-Python accumulation in
    ``srmech.cascade.cayley_dickson.table_product`` is the complete,
    byte-identical alternative (and the parity oracle)."""
    if not (HAS_NATIVE and LIB is not None):
        return False
    return (hasattr(LIB, "srmech_algebra_table_product")
            and hasattr(LIB, "srmech_algebra_table_product_ws_bound")
            and hasattr(LIB, "srmech_algebra_table_product_entry_cap")
            and hasattr(LIB, "srmech_bigint_from_dec")
            and hasattr(LIB, "srmech_bigint_to_dec"))


def algebra_table_product_c(flat_table, dim: int,
                            x_components, y_components) -> "list | None":
    """Native table-driven exact-ℚ product ``(x·y)_k = Σ_ij t[i][j][k]·x_i·y_j``
    → list of ``dim`` reduced ``(num, den)`` tuples, or None (no-C / pre-rc352
    lib). ``flat_table`` is the row-major ``dim³`` integer sequence; ``x`` /
    ``y`` are ``dim``-length ``(num, den)`` sequences.

    Sized for a DENSE table (every one of the ``dim²`` products may land in one
    output slot), so the arena is wider than ``cd_mult``'s; a too-small arena →
    OVERFLOW → None → the caller's pure exact-ℚ oracle."""
    if not has_native_algebra_table_product():
        return None
    d = int(dim)
    if len(x_components) != d or len(y_components) != d:
        return None
    if len(flat_table) != d * d * d:
        return None
    cl = max(_poly_coeff_limbs(x_components), _poly_coeff_limbs(y_components))
    out_cap = int(LIB.srmech_algebra_table_product_entry_cap(
        ctypes.c_size_t(cl), ctypes.c_size_t(d)))
    ws_len = int(LIB.srmech_algebra_table_product_ws_bound(
        ctypes.c_size_t(cl), ctypes.c_size_t(d)))
    ws = (ctypes.c_uint8 * max(ws_len, 8))()
    tbuf = (ctypes.c_int64 * (d * d * d))(*[int(v) for v in flat_table])
    x_n, x_d, kx = _poly_make_array(x_components, out_cap)
    y_n, y_d, ky = _poly_make_array(y_components, out_cap)
    o_n, o_d, ko = _poly_blank_array(d, out_cap)
    rc = LIB.srmech_algebra_table_product(
        tbuf, d, x_n, x_d, y_n, y_d, o_n, o_d,
        ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len))
    _ = (kx, ky, ko)
    if rc != SRMECH_OK:
        return None
    return _poly_read_array(o_n, o_d, d)


