def has_native_file_open_counter() -> bool:
    """True iff the rc296 PAL read-path open counter is loaded + bound.

    The counter is DIAGNOSTIC instrumentation, not an op: it exists so a test can
    measure how many times the COMPILED projection opens a file during a span of
    work. Python's ``builtins.open`` / ``Path.open`` hooks are blind to an ``fopen``
    inside ``libsrmech``, so before rc296 the compiled read path's open shape was
    unmeasurable from the suite — and the rc282 down-only open ratchet, whose every
    test forced the pure path, silently constrained one projection only."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_plat_file_opens")
                and hasattr(LIB, "srmech_plat_file_opens_reset"))


def file_opens_c() -> int:
    """Read-path opens (``file_read`` / ``file_read_region`` / ``file_open_ro`` /
    ``file_size`` / ``rstream_open``) the C library has performed since process
    start or the last :func:`file_opens_reset_c`. Writes are NOT counted.

    Counts ATTEMPTS, not successes — the same thing ``strace -e trace=openat``
    records, so the counter and the strace probe measure one quantity. Returns 0
    when the counter is absent; a caller that needs the difference should gate on
    :func:`has_native_file_open_counter` rather than read 0 as a measurement."""
    if not has_native_file_open_counter():
        return 0
    return int(LIB.srmech_plat_file_opens())


def file_opens_reset_c() -> None:
    """Zero the rc296 read-path open counter. No-op when the counter is absent."""
    if not has_native_file_open_counter():
        return
    LIB.srmech_plat_file_opens_reset()


#: The rc280 section-counts first-call distinct-id capacity. It sizes BOTH the out
#: arrays AND (rc306) the C count table + caller ws, which is why the two overflow on
#: the SAME knob: a store with more distinct ids reports its true need via ``n_out``
#: (an exact retry) or overflows the table mid-scan (a geometric grow), and each retry
#: re-sizes ws — so the arena is never over-allocated for a small store nor short for
#: a corpus-scale one, with no compiled-in ceiling.
_SECTION_COUNTS_CAP0: int = 1 << 16
#: Bound on the retry-grow loop (geometric *4 on a table overflow) so a pathological
#: input degrades to a pure-body DECLINE rather than looping forever.
_SECTION_COUNTS_MAX_ATTEMPTS: int = 12


def genome_section_counts_c(store, coupling, leaf_dim, progress=None,
                            *, body_len=None, n_chroms=None):
    """Native §102/rc280 section-count derivation (parity peer
    ``srmech_genome_section_counts``): scan a plasmid section store and return
    ``(ids, counts, n_done, cancelled)`` — ``ids`` ascending, ``counts[i]`` the number
    of DISTINCT sections carrying ``ids[i]``, the VOCAB chromosome excluded.

    The C peer derives the store catalog ONCE and, per section, pages only the
    ``node_ids`` prefix of the region — never the edge bytes — which is what makes the
    scan O(P × node_ids) instead of O(P² × body). ``progress`` is the Python-only §101
    tick (a truthy return CANCELS at a section boundary; the partial counts still come
    back, and the Python caller raises rather than returning them).

    **rc306 (task #899) — the caller supplies the arena.** The C op no longer owns a
    32 MiB static catalog arena (which capped the corpus at ~11k sections) or a static
    count table / window. This binding sizes ``ws`` with the C
    ``srmech_genome_section_counts_arena_bytes(body_len, n_chroms, cap)`` helper — so
    ``body_len`` (turns.bin bytes) and ``n_chroms`` (manifest chromosome count incl.
    vocab) are REQUIRED to run native; without them this DECLINES to the pure body. On
    a count-table / out-array overflow it grows ``cap`` and re-sizes ``ws`` (exact when
    the table held the ids and only the out arrays were short; geometric otherwise) so
    a corpus with any number of distinct ids censuses natively given enough memory.

    Returns ``None`` to DECLINE (symbol absent / bad shape / unsizable arena) so the
    pure body runs. Value-identical to the pure ``section_counts``."""
    if not has_native_genome_section_counts():
        return None
    if not (LIB is not None
            and hasattr(LIB, "srmech_genome_section_counts_arena_bytes")):
        return None                       # rc306 ws-sizing helper is required
    try:
        dim = int(leaf_dim)
        one = bytes(coupling)
        if dim <= 0 or dim > 256 or len(one) != dim:
            return None
        if body_len is None or n_chroms is None:
            return None                   # the caller must size the arena (see above)
        blen = int(body_len)
        nchr = int(n_chroms)
        if blen < 0 or nchr < 0:
            return None
        path = str(store).encode("utf-8")
        one_arr = (ctypes.c_uint8 * dim)(*one)
        cap = _SECTION_COUNTS_CAP0
        for _attempt in range(_SECTION_COUNTS_MAX_ATTEMPTS):
            ws_len = int(LIB.srmech_genome_section_counts_arena_bytes(
                ctypes.c_size_t(blen), ctypes.c_uint32(nchr), ctypes.c_size_t(cap)))
            if ws_len <= 0:
                return None
            ws = (ctypes.c_char * ws_len)()
            ids = (ctypes.c_uint64 * cap)()
            cnts = (ctypes.c_uint64 * cap)()
            n_out = ctypes.c_size_t(0)
            n_done = ctypes.c_size_t(0)
            box: dict = {}
            tick = _make_tick_trampoline(progress, box) if progress is not None else \
                ctypes.cast(None, _TICK_CFUNCTYPE)
            rc = LIB.srmech_genome_section_counts(
                path,                       # bytes -> NUL-terminated const char *
                one_arr, ctypes.c_uint32(dim),
                tick, None,
                ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len),
                ids, cnts, ctypes.c_size_t(cap),
                ctypes.byref(n_out), ctypes.byref(n_done))
            if box.get("exc") is not None:
                raise box["exc"]
            if rc == SRMECH_ERR_OVERFLOW:
                need = int(n_out.value)
                if need > cap:
                    cap = need              # table held the ids; out arrays were short — exact retry
                else:
                    cap = cap * 4 + 1       # count table / ws too small — grow geometrically
                continue
            if rc not in (SRMECH_OK, SRMECH_CANCELLED):
                return None
            n = int(n_out.value)
            return ([int(ids[i]) for i in range(n)],
                    [int(cnts[i]) for i in range(n)],
                    int(n_done.value), rc == SRMECH_CANCELLED)
        return None
    except Exception:
        return None


def has_native_genome_integrate_plasmids() -> bool:
    """True iff the §102/rc279 srmech_genome_integrate_plasmids C orchestrator is
    loaded + bound: a bare-C host runs stage 2 (PROMOTE the conserved core via
    mint_strand, MERGE the retained plasmids via integrate) end-to-end, with the §101
    tick firing between whole chromosomes. False on a no-C or pre-rc279 lib — the pure
    srmech.biology.plasmid fold is the complete byte-identical alternative."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_integrate_plasmids"))


def genome_integrate_plasmids_c(core, core_blocks, plasmids, plasmid_blocks,
                                leaf_dim, coupling, progress=None,
                                centromere_at=-1, repeats=None, handle=b"cen"):
    """Native §102/rc279 ORGANIZE (parity peer srmech_genome_integrate_plasmids): mint
    the conserved core (0x58 centromere) and fold in the retained plasmid sections,
    returning ``(strand_hvs, n_integrated, cancelled)``. ``core`` / ``plasmids`` are
    concatenated leaf_dim-byte block bytes; ``plasmid_blocks`` the per-section block
    counts. ``progress`` is the Python-only tick (a truthy return CANCELS at a
    chromosome boundary -> a valid shorter organized genome). Returns ``None`` to
    DECLINE so the pure fold runs. Byte-identical to the pure path."""
    if not has_native_genome_integrate_plasmids():
        return None
    from ..biology.genome import _hv_from_block, CENTROMERE_DEFAULT_REPEATS
    try:
        dim = int(leaf_dim)
        one = bytes(coupling)
        if dim <= 0 or dim > 256 or len(one) != dim:
            return None
        hnd = bytes(handle) if handle else b""
        n_p = len(plasmid_blocks)
        total_blocks = int(core_blocks) + 1 + sum(int(b) for b in plasmid_blocks)
        blk_arr = (ctypes.c_size_t * max(n_p, 1))(*[int(b) for b in plasmid_blocks])
        one_arr = (ctypes.c_uint8 * dim)(*one)
        out = (ctypes.c_uint8 * (total_blocks * dim))()
        ws = (ctypes.c_uint8 * ((int(core_blocks) + 1) * dim))()
        nb = ctypes.c_size_t(0)
        n_int = ctypes.c_size_t(0)
        box: dict = {}
        tick = _make_tick_trampoline(progress, box) if progress is not None else \
            ctypes.cast(None, _TICK_CFUNCTYPE)
        rc = LIB.srmech_genome_integrate_plasmids(
            (ctypes.c_uint8 * len(core)).from_buffer_copy(core) if core else None,
            ctypes.c_size_t(int(core_blocks)),
            (ctypes.c_uint8 * len(plasmids)).from_buffer_copy(plasmids)
            if plasmids else None,
            blk_arr, ctypes.c_size_t(n_p),
            ctypes.c_uint32(dim), one_arr,
            ctypes.c_long(int(centromere_at)),
            ctypes.c_uint32(CENTROMERE_DEFAULT_REPEATS if repeats is None
                            else int(repeats)),
            # the CENP-A inline epigenetic address — MUST match the Python
            # mint_strand default (handle="cen"), or the cap bytes diverge.
            (ctypes.c_uint8 * len(hnd)).from_buffer_copy(hnd) if hnd else None,
            ctypes.c_size_t(len(hnd)),
            tick, None,
            out, ctypes.c_size_t(total_blocks * dim),
            ctypes.byref(nb), ctypes.byref(n_int),
            ws, ctypes.c_size_t((int(core_blocks) + 1) * dim))
        if box.get("exc") is not None:
            raise box["exc"]
        if rc not in (SRMECH_OK, SRMECH_CANCELLED):
            return None
        raw = bytes(out)[:nb.value * dim]
        strand = [_hv_from_block(raw[i * dim:(i + 1) * dim])
                  for i in range(nb.value)]
        return strand, int(n_int.value), rc == SRMECH_CANCELLED
    except Exception:
        return None


def has_native_genome_add_plasmid() -> bool:
    """True iff the §102/rc334 srmech_genome_add_plasmid whole-op C peer (task #887)
    is loaded + bound — the LAST genome wire-glue gap closed (CEIL_WIRE_GLUE_GAPS
    1 -> 0). A bare-C host runs one incremental add's CONSERVE + ORGANIZE half
    (merge counts -> conserved_core -> harvest+pack the core off disk -> fold the
    organized strand) end-to-end. False on a no-C or pre-rc334 lib — the pure
    srmech.biology.plasmid.add_plasmid body is the complete byte-identical alternative."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_add_plasmid")
                and hasattr(LIB, "srmech_genome_add_plasmid_scratch_bytes")
                and hasattr(LIB, "srmech_genome_section_counts_arena_bytes"))


def genome_add_plasmid_c(store, coupling, leaf_dim, k_in, prior_counts, new_nid,
                         prior_core, *, body_len, n_chroms, progress=None,
                         centromere_at=-1, repeats=None, handle=b"cen"):
    """Native §102/rc334 incremental add (parity peer srmech_genome_add_plasmid): the
    CONSERVE + ORGANIZE half of one add_plasmid, run END-TO-END in C over the store
    (the new section ALREADY appended by the Python plasmid_extract, which seeds +
    refreshes the vocab karyotype).

    ``prior_counts`` is the PRIOR section-count accumulator (a ``{global_id: n}`` dict);
    ``new_nid`` the new section's UNIQUE global node_ids; ``prior_core`` the prior
    conserved core (for ``core_changed``); ``k_in`` the conservation threshold (< 0 =
    DERIVE from the antimode, >= 0 = force). ``body_len`` (turns.bin bytes) + ``n_chroms``
    (manifest chromosome count incl. vocab) size the caller arenas.

    Returns ``(strand_hvs, counts_dict, core_list, k, bimodal, core_changed,
    n_integrated, cancelled)`` — byte-identical to the pure add_plasmid strand + the
    section_count/core/k state — or ``None`` to DECLINE so the pure body runs."""
    if not has_native_genome_add_plasmid():
        return None
    from ..biology.genome import _hv_from_block, CENTROMERE_DEFAULT_REPEATS
    try:
        dim = int(leaf_dim)
        one = bytes(coupling)
        if dim < 52 or dim > 256 or len(one) != dim:
            return None
        if body_len is None or n_chroms is None:
            return None
        pri = sorted((int(k), int(v)) for k, v in dict(prior_counts).items())
        p_ids = [k for k, _ in pri]
        p_cnt = [v for _, v in pri]
        n_prior = len(p_ids)
        nn = [int(x) for x in new_nid]
        n_new = len(nn)
        pc = [int(x) for x in prior_core]
        n_pcore = len(pc)
        counts_cap = n_prior + n_new + 1
        core_cap = counts_cap
        hnd = bytes(handle) if handle else b""
        reps = CENTROMERE_DEFAULT_REPEATS if repeats is None else int(repeats)
        one_arr = (ctypes.c_uint8 * dim)(*one)
        p_ids_arr = (ctypes.c_uint64 * max(n_prior, 1))(*p_ids)
        p_cnt_arr = (ctypes.c_uint64 * max(n_prior, 1))(*p_cnt)
        nn_arr = (ctypes.c_uint64 * max(n_new, 1))(*nn)
        pc_arr = (ctypes.c_uint64 * max(n_pcore, 1))(*pc)
        hnd_arr = ((ctypes.c_uint8 * len(hnd)).from_buffer_copy(hnd) if hnd
                   else ctypes.cast(None, ctypes.POINTER(ctypes.c_uint8)))
        # the manifest arena (the tree persists across the section passes); the
        # section_counts sizer's catalog term is exactly srmech_genome_arena_bytes.
        ws_len = int(LIB.srmech_genome_section_counts_arena_bytes(
            ctypes.c_size_t(int(body_len)), ctypes.c_uint32(int(n_chroms)),
            ctypes.c_size_t(1)))
        if ws_len <= 0:
            return None
        ws = (ctypes.c_char * ws_len)()
        out_ids = (ctypes.c_uint64 * counts_cap)()
        out_counts = (ctypes.c_uint64 * counts_cap)()
        out_core = (ctypes.c_uint64 * core_cap)()
        n_counts = ctypes.c_size_t(0)
        n_core = ctypes.c_size_t(0)
        out_k = ctypes.c_uint64(0)
        out_bimodal = ctypes.c_int(0)
        out_changed = ctypes.c_int(0)
        n_integ = ctypes.c_size_t(0)
        cancelled = ctypes.c_uint32(0)
        scratch_len = max(int(LIB.srmech_genome_add_plasmid_scratch_bytes(
            ctypes.c_size_t(int(body_len)), ctypes.c_size_t(n_new),
            ctypes.c_uint32(dim))), 4096)
        out_cap = max(int(body_len) * 6 + int(n_chroms) * dim + 4096, dim)
        for _attempt in range(6):
            scratch = (ctypes.c_char * scratch_len)()
            out = (ctypes.c_uint8 * out_cap)()
            out_nblocks = ctypes.c_size_t(0)
            box: dict = {}
            tick = _make_tick_trampoline(progress, box) if progress is not None else \
                ctypes.cast(None, _TICK_CFUNCTYPE)
            rc = LIB.srmech_genome_add_plasmid(
                str(store).encode("utf-8"), one_arr, ctypes.c_uint32(dim),
                ctypes.c_long(int(k_in)),
                p_ids_arr, p_cnt_arr, ctypes.c_size_t(n_prior),
                nn_arr, ctypes.c_size_t(n_new),
                pc_arr, ctypes.c_size_t(n_pcore),
                ctypes.c_long(int(centromere_at)), ctypes.c_uint32(reps),
                hnd_arr, ctypes.c_size_t(len(hnd)),
                tick, None,
                out_ids, out_counts, ctypes.c_size_t(counts_cap),
                ctypes.byref(n_counts),
                out_core, ctypes.c_size_t(core_cap), ctypes.byref(n_core),
                ctypes.byref(out_k), ctypes.byref(out_bimodal),
                ctypes.byref(out_changed),
                out, ctypes.c_size_t(out_cap), ctypes.byref(out_nblocks),
                ctypes.byref(n_integ), ctypes.byref(cancelled),
                ctypes.cast(ws, ctypes.c_void_p), ctypes.c_size_t(ws_len),
                ctypes.cast(scratch, ctypes.c_void_p), ctypes.c_size_t(scratch_len))
            if box.get("exc") is not None:
                raise box["exc"]
            if rc == SRMECH_ERR_OVERFLOW:
                scratch_len = scratch_len * 2 + 1
                out_cap = out_cap * 2 + dim
                continue
            if rc not in (SRMECH_OK, SRMECH_CANCELLED):
                return None
            nb = int(out_nblocks.value)
            raw = bytes(out)[:nb * dim]
            strand = [_hv_from_block(raw[i * dim:(i + 1) * dim]) for i in range(nb)]
            counts = {int(out_ids[i]): int(out_counts[i])
                      for i in range(int(n_counts.value))}
            core = [int(out_core[i]) for i in range(int(n_core.value))]
            return (strand, counts, core, int(out_k.value), bool(out_bimodal.value),
                    bool(out_changed.value), int(n_integ.value),
                    rc == SRMECH_CANCELLED)
        return None
    except Exception:
        return None


def has_native_eulerian() -> bool:
    """True iff the rc250 srmech_eulerian_walk C peer is loaded + bound: the
    #1390 item-3 Hierholzer Eulerian trail / circuit runs in C (integer nodes).
    False on a no-C or pre-rc250 lib — the pure
    srmech.math.laplacian.eulerian_path / eulerian_circuit bodies are the
    complete byte-identical alternative + parity oracle."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_eulerian_walk"))


def eulerian_walk_c(edges, n_nodes, start, circuit_only):
    """Native #1390 item-3 Eulerian walk (integer nodes [0, n_nodes)). Returns
    the walk (list[int]) on success, ``None`` if infeasible (the pure ``None``).
    Raises on a C error so the caller falls back to the pure body."""
    n_edges = len(edges)
    eu = (ctypes.c_uint64 * max(n_edges, 1))(*[int(e[0]) for e in edges])
    ev = (ctypes.c_uint64 * max(n_edges, 1))(*[int(e[1]) for e in edges])
    outdeg = (ctypes.c_uint64 * max(n_nodes, 1))()
    indeg = (ctypes.c_uint64 * max(n_nodes, 1))()
    cur = (ctypes.c_size_t * max(n_nodes, 1))()
    adj_start = (ctypes.c_size_t * (n_nodes + 1))()
    adj = (ctypes.c_uint64 * max(n_edges, 1))()
    stack = (ctypes.c_uint64 * (n_edges + 1))()
    out_walk = (ctypes.c_uint64 * (n_edges + 1))()
    wl = ctypes.c_size_t(0)
    feasible = ctypes.c_int(0)
    rc = LIB.srmech_eulerian_walk(
        eu, ev, ctypes.c_size_t(n_edges), ctypes.c_uint64(n_nodes),
        ctypes.c_int64(start), ctypes.c_int(1 if circuit_only else 0),
        outdeg, indeg, adj_start, cur, adj, stack, out_walk,
        ctypes.byref(wl), ctypes.byref(feasible))
    if rc != SRMECH_OK:
        raise RuntimeError(f"srmech_eulerian_walk returned status {rc}")
    if not feasible.value:
        return None
    return [int(out_walk[k]) for k in range(wl.value)]


def genome_telomere_tick_c(cap: bytes, leaf_dim: int):
    """Native §127 active-telomere tick — the divide/gate (the operand modulates the
    operator). Returns ``(senescent: bool, count_after: int, new_cap: bytes)``:
    ``senescent`` True iff the count was 0 (Hayflick refuse; ``new_cap`` == ``cap``),
    else ``count_after`` == count-1 and ``new_cap`` is the decremented daughter cap.
    Byte-identical to the pure Python ``telomere_tick``."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_telomere_tick"):
        raise NativeGenomeError("srmech_genome_telomere_tick", SRMECH_ERR_NOT_IMPL)
    out = (ctypes.c_uint8 * max(leaf_dim, 1))()
    senescent = ctypes.c_int(0)
    count_after = ctypes.c_uint64(0)
    rc = LIB.srmech_genome_telomere_tick(
        _u8(cap), ctypes.c_size_t(leaf_dim), out,
        ctypes.byref(senescent), ctypes.byref(count_after))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_telomere_tick", rc)
    return bool(senescent.value), int(count_after.value), bytes(out[:leaf_dim])


def has_native_genome_encode_shape() -> bool:
    """True iff the rc196 srmech_genome_encode_shape C peer is loaded + bound.
    False on a no-C or pre-rc196 lib — the pure ``srmech.biology.genome.encode_shape``
    integer body is the complete alternative (and the parity oracle)."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_encode_shape"))


def genome_encode_shape_c(n: int):
    """Native §44/F715 shape planner (parity peer ``srmech_genome_encode_shape``):
    ``n`` (a positive kernel size) → ``(leaves, depth)`` ints, where
    ``leaves = ceil(n / 256)`` and ``depth = ceil(log4(leaves))``. Returns ``None``
    when the symbol is absent OR ``n`` is out of the uint64 fast-path range
    (``n <= 0`` / ``n >= 2**64``) — the caller runs the exact pure Python (which
    also raises the ValueError for ``n <= 0``). Byte-identical to the arithmetic in
    the pure ``encode_shape``; the caller maps depth → shape + builds the dict."""
    if not has_native_genome_encode_shape():
        return None
    if not isinstance(n, int) or isinstance(n, bool) or n <= 0 or n >= (1 << 64):
        return None
    leaves = ctypes.c_uint64(0)
    depth = ctypes.c_uint32(0)
    rc = LIB.srmech_genome_encode_shape(
        ctypes.c_uint64(n), ctypes.byref(leaves), ctypes.byref(depth))
    if rc != SRMECH_OK:
        return None
    return int(leaves.value), int(depth.value)


def has_native_genome_active_telomere() -> bool:
    """True iff the rc329 §127/G7 srmech_genome_active_telomere C peer is loaded +
    bound: a bare-C host packs ONE §127 active-telomere cap (the op⊗operand Hayflick
    cap) with no daughter-minting. False on a no-C or pre-rc329 lib — the pure
    ``srmech.biology.genome._pack_active_telomere`` body is the complete byte-identical
    alternative + parity oracle."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_active_telomere"))


def genome_active_telomere_c(label, count: int, leaf_dim: int):
    """Native §127/G7 active-telomere packer (parity peer
    ``srmech_genome_active_telomere``): ``(label, count, leaf_dim)`` → the packed
    ``leaf_dim``-byte cap bytes ``[0x74] + utf-8(label) + NUL + count(uint64 BE)``,
    NUL-padded. Returns ``None`` when the symbol is absent OR the inputs do not fit
    the fast path (``count`` out of the uint64 field, a NUL byte in the label, or the
    ``[marker+label+NUL+count]`` payload over ``leaf_dim``) — the caller then runs the
    exact pure ``_pack_active_telomere`` (which raises the matching ValueError).
    Byte-identical to the bytes behind the Python cap (wrapped in HV(sectors=256))."""
    if not has_native_genome_active_telomere():
        return None
    if (not isinstance(count, int) or isinstance(count, bool)
            or count < 0 or count >= (1 << 64)):
        return None
    raw = label.encode("utf-8") if isinstance(label, str) else bytes(label)
    if leaf_dim <= 0 or b"\x00" in raw or (2 + len(raw) + 8) > leaf_dim:
        return None
    out = (ctypes.c_uint8 * leaf_dim)()
    rc = LIB.srmech_genome_active_telomere(
        _u8(raw), ctypes.c_size_t(len(raw)), ctypes.c_uint64(count),
        ctypes.c_uint32(leaf_dim), out, ctypes.c_size_t(leaf_dim))
    if rc != SRMECH_OK:
        return None
    return bytes(out[:leaf_dim])


def has_native_genome_mint_plan() -> bool:
    """True iff the rc329 §102/G7 srmech_genome_mint_plan C peer is loaded + bound: a
    bare-C host runs the WHOLE mint_plan read-loop (encode_shape + the content-address
    orientation per kernel) with no Python present. False on a no-C or pre-rc329 lib —
    the pure ``srmech.biology.genome.mint_plan`` body is the complete byte-identical
    alternative + parity oracle."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_mint_plan"))


def genome_mint_plan_c(contents, leaf_counts):
    """§102/G7 native dispatch for :func:`srmech.biology.genome.mint_plan`. Runs the WHOLE
    read-loop in C via ``srmech_genome_mint_plan``: per kernel the F715 shape decision
    (``srmech_genome_encode_shape`` → plasmid vs nuclear) and, for a nuclear kernel, its
    content-addressed orientation (``sha256(content)[0] & 3``).

    ``contents`` is the per-kernel content preimage bytes (each ==
    ``genome._kernel_content_bytes(leaves)``); ``leaf_counts`` the per-kernel leaf count
    (the plan's ``n_leaves``). Returns a list of ``(is_nuclear: int, orientation: int)``
    per kernel (``orientation`` is 0 for a plasmid — the caller maps that to ``None``),
    or ``None`` when the symbol is absent / the C op declines, so the caller takes the
    pure body (the byte-parity oracle)."""
    if not has_native_genome_mint_plan():
        return None
    n = len(contents)
    if n != len(leaf_counts):
        return None
    flat = b"".join(bytes(c) for c in contents)
    clens = (ctypes.c_size_t * max(n, 1))(*[len(bytes(c)) for c in contents])
    lcounts = (ctypes.c_size_t * max(n, 1))(*[int(x) for x in leaf_counts])
    is_nuc = (ctypes.c_uint8 * max(n, 1))()
    orient = (ctypes.c_uint8 * max(n, 1))()
    rc = LIB.srmech_genome_mint_plan(
        _u8(flat), clens, lcounts, ctypes.c_size_t(n), is_nuc, orient)
    if rc != SRMECH_OK:
        return None
    return [(int(is_nuc[i]), int(orient[i])) for i in range(n)]


