def genome_chromatin_gated_c(chromatin_type, num, den, gate_blob, handle, dim: int):
    """Native §98.1/G1 FACULTATIVE chromatin cap writer (parity peer
    ``srmech_genome_chromatin_gated``): the constitutive ``[0x48] + handle + NUL + type + num + den``
    with ``gate_blob = [access_gate_type] + payload`` appended VERBATIM after ``den``, NUL-padded to
    ``dim`` — the packed ``dim``-byte cap bytes, or ``None`` when the symbol is absent OR the inputs
    are invalid (the caller runs the pure ``_pack_chromatin``, the parity oracle). ``gate_blob`` is
    the already-serialised bytes from ``genome._chromatin_gate_blob`` (non-empty — a NONE cap routes
    through ``genome_chromatin_c``). Byte-identical to the pure path."""
    if not has_native_genome_chromatin_gated():
        return None
    raw = handle.encode("utf-8") if isinstance(handle, str) else bytes(handle)
    blob = bytes(gate_blob)
    if (not isinstance(chromatin_type, int) or isinstance(chromatin_type, bool)
            or chromatin_type not in (0, 1)
            or not isinstance(num, int) or isinstance(num, bool)
            or not isinstance(den, int) or isinstance(den, bool)
            or den < 1 or num < 0 or num > den or den >= (1 << 64)
            or b"\x00" in raw or dim <= 0 or 3 + len(raw) + 16 + len(blob) > dim):
        return None
    out = (ctypes.c_uint8 * dim)()
    rc = LIB.srmech_genome_chromatin_gated(
        ctypes.c_uint8(chromatin_type), ctypes.c_uint64(num), ctypes.c_uint64(den),
        _u8(blob), ctypes.c_size_t(len(blob)),
        _u8(raw), ctypes.c_size_t(len(raw)), ctypes.c_uint32(dim),
        out, ctypes.c_size_t(dim))
    if rc != SRMECH_OK:
        return None
    return bytes(out[:dim])


def has_native_genome_partition() -> bool:
    """True iff the rc198 srmech_genome_partition C peer is loaded + bound. False on a
    no-C or pre-rc198 lib — the pure ``srmech.biology.genome.partition`` body is the
    complete alternative (and the parity oracle)."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_partition"))


def genome_partition_c(strand: bytes, n_blocks: int, leaf_dim: int, coupling: bytes):
    """Native rc198 partition (parity peer ``srmech_genome_partition``): walk the
    ``n_blocks`` fixed-width ``leaf_dim``-byte blocks of ``strand``; a CHROM /
    kernel-telomere / active-telomere cap opens a partition (label read inline), a
    gene / header cap is skipped (flatten), each data turn until the next opening cap
    is re-bound through ``coupling`` as that partition's leaf. Returns
    ``(leaf_bytes, labels, counts)`` — ``leaf_bytes`` the recovered leaves
    (``n_leaves × leaf_dim``, partition order), ``labels`` the per-partition label
    strings, ``counts`` the per-partition leaf counts — or ``None`` when the symbol is
    absent OR the inputs do not fit the fast path (width mismatch, a data byte > 3).
    The caller builds ``{label: [leaves]}`` (dict overwrite-on-duplicate-label) and
    applies any ``labels=`` filter — byte-identical to ``partition``."""
    if not has_native_genome_partition():
        return None
    if (leaf_dim <= 0 or leaf_dim > 256 or len(coupling) != leaf_dim
            or len(strand) != n_blocks * leaf_dim):
        return None
    cap = max(n_blocks * leaf_dim, 1)
    out_leaves = (ctypes.c_uint8 * cap)()
    out_labels = (ctypes.c_uint8 * cap)()
    part_counts = (ctypes.c_uint32 * max(n_blocks, 1))()
    n_parts = ctypes.c_size_t(0)
    n_leaves = ctypes.c_size_t(0)
    rc = LIB.srmech_genome_partition(
        _u8(strand), ctypes.c_size_t(n_blocks), ctypes.c_uint32(leaf_dim),
        _u8(coupling), out_leaves, ctypes.c_size_t(n_blocks * leaf_dim),
        out_labels, ctypes.c_size_t(n_blocks * leaf_dim),
        part_counts, ctypes.c_size_t(n_blocks),
        ctypes.byref(n_parts), ctypes.byref(n_leaves))
    if rc != SRMECH_OK:
        return None
    np_ = int(n_parts.value)
    nl = int(n_leaves.value)
    leaf_bytes = bytes(out_leaves[:nl * leaf_dim])
    labels = []
    for p in range(np_):
        slot = bytes(out_labels[p * leaf_dim:(p + 1) * leaf_dim])
        labels.append(slot.split(b"\x00", 1)[0].decode("utf-8"))
    counts = [int(part_counts[p]) for p in range(np_)]
    return leaf_bytes, labels, counts


def has_native_genome_integrate() -> bool:
    """True iff the §95.1d/rc276 srmech_genome_integrate C peer is loaded + bound.
    False on a no-C or pre-rc276 lib — the pure ``srmech.biology.genome.integrate`` body
    is the complete alternative (and the parity oracle)."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_integrate"))


def genome_integrate_c(host: bytes, host_blocks: int, host_leaf_dim: int,
                       provirus: bytes, prov_blocks: int, prov_leaf_dim: int,
                       at: int):
    """Native §95.1d/rc276 INTEGRATE (parity peer ``srmech_genome_integrate``): splice
    ``provirus`` INTO ``host`` at the chromosome boundary resolved from ``at`` — the host
    chromosome index to insert the provirus BEFORE (0-based); ``at < 0`` = after the last
    chromosome (the Python ``at=None`` default). Scans the host's ``host_leaf_dim``-byte
    blocks for chromosome-boundary caps, then concatenates
    ``host[:locus] + provirus + host[locus:]`` byte-identically. Returns
    ``(out_bytes, integrated)`` — ``out_bytes`` the spliced strand
    (``(host_blocks + prov_blocks) × prov_leaf_dim`` bytes) and ``integrated`` True on a
    compatible splice / False on the §135/F1251 width-coherence HONEST-DECLINE — or
    ``None`` when the symbol is absent OR the inputs do not fit the fast path (a byte
    length not matching ``n_blocks × leaf_dim``, an out-of-range ``at``). Byte-identical
    to the pure ``integrate`` splice."""
    if not has_native_genome_integrate():
        return None
    if (prov_leaf_dim <= 0 or prov_leaf_dim > 256 or prov_blocks <= 0
            or len(provirus) != prov_blocks * prov_leaf_dim):
        return None
    if host_blocks > 0 and (host_leaf_dim <= 0 or host_leaf_dim > 256
                            or len(host) != host_blocks * host_leaf_dim):
        return None
    out_cap = (host_blocks + prov_blocks) * prov_leaf_dim
    out = (ctypes.c_uint8 * max(out_cap, 1))()
    n_blocks = ctypes.c_size_t(0)
    integrated = ctypes.c_int(0)
    rc = LIB.srmech_genome_integrate(
        _u8(host), ctypes.c_size_t(host_blocks), ctypes.c_uint32(host_leaf_dim),
        _u8(provirus), ctypes.c_size_t(prov_blocks), ctypes.c_uint32(prov_leaf_dim),
        ctypes.c_long(at), out, ctypes.c_size_t(out_cap),
        ctypes.byref(n_blocks), ctypes.byref(integrated))
    if rc != SRMECH_OK:
        return None
    if int(integrated.value) == 0:
        return b"", False
    nb = int(n_blocks.value)
    return bytes(out[:nb * prov_leaf_dim]), True


def has_native_genome_mint_strand() -> bool:
    """True iff the §100 GAP 1/rc277 srmech_genome_mint_strand C peer is loaded + bound.
    False on a no-C or pre-rc277 lib — the pure ``srmech.biology.genome.mint_strand`` body is
    the complete alternative (and the parity oracle)."""
    return bool(HAS_NATIVE and LIB is not None
                and hasattr(LIB, "srmech_genome_mint_strand"))


def genome_mint_strand_c(strand: bytes, n_blocks: int, leaf_dim: int, coupling: bytes,
                         centromere_at: int, orientation, repeats: int, handle: bytes):
    """Native §100 GAP 1/rc277 MINT-STRAND (parity peer ``srmech_genome_mint_strand``):
    PROMOTE an already-packed ``strand`` to a Tier-2 nuclear chromosome by splicing a §95a
    interior centromere (0x58) at the p:q arm-split. Scans the strand's ``leaf_dim``-byte
    DATA turns, content-addresses the global orientation from the strand's OWN recovered
    leaves (recall -> ``sha256(leaves)[0] & 3``) when ``orientation is None``, writes the
    centromere cap, and concatenates ``strand[:locus] + cap + strand[locus:]`` byte-
    identically. ``centromere_at`` is the resolved arm-split (data-turn index; ``< 0`` = the
    metacentric midpoint); ``orientation`` is ``None`` (content-address) or a 0..3 sector;
    ``handle`` the CENP-A epigenetic address bytes. Returns the minted strand bytes
    (``(n_blocks + 1) × leaf_dim``), or ``None`` when the symbol is absent OR the inputs do
    not fit the fast path (a byte length not matching ``n_blocks × leaf_dim``). Byte-
    identical to the pure ``mint_strand`` splice."""
    if not has_native_genome_mint_strand():
        return None
    if (leaf_dim <= 0 or leaf_dim > 256 or n_blocks <= 0
            or len(strand) != n_blocks * leaf_dim or len(coupling) != leaf_dim):
        return None
    auto = 1 if orientation is None else 0
    o = 0 if orientation is None else int(orientation)
    out_cap = (n_blocks + 1) * leaf_dim
    out = (ctypes.c_uint8 * out_cap)()
    n_out = ctypes.c_size_t(0)
    rc = LIB.srmech_genome_mint_strand(
        _u8(strand), ctypes.c_size_t(n_blocks), ctypes.c_uint32(leaf_dim),
        _u8(coupling), ctypes.c_long(centromere_at), ctypes.c_uint8(o & 0xFF),
        ctypes.c_int(auto), ctypes.c_uint32(repeats),
        _u8(handle), ctypes.c_size_t(len(handle)),
        out, ctypes.c_size_t(out_cap), ctypes.byref(n_out))
    if rc != SRMECH_OK:
        return None
    nb = int(n_out.value)
    return bytes(out[:nb * leaf_dim])


def genome_gene_express_c(cap: bytes, leaf_dim: int, cell_state: int) -> bool:
    """Native §128/§129 per-gene expression decision — the read-time filter (the cell_state
    operand modulates the operator). ``cap`` is a plain GENE (0x47) or regulatory-gene
    (0x67) cap leaf; returns ``True`` iff the gene EXPRESSES under ``cell_state``: a plain
    gene always expresses (masks 0), a regulatory gene carries the TWO KLEIN-4 bit-planes
    (activator then repressor) and expresses iff ``(cell_state & activator) == activator``
    (ALL activators present) AND ``(cell_state & repressor) == 0`` (NO repressor present).
    §129 dual-read: a rc128 single-mask cap reads as activator=mask, repressor=0. §130: a boolean
    gene (0x62) carries a DNF and expresses iff ANY clause matches. §131: a threshold gene (0x77)
    carries a linear-threshold / perceptron gate (a SIGNED int64 weight per condition + an int64
    threshold) and expresses iff ``Σ weightᵢ·bit_i(cell_state) ≥ threshold`` (Class-K sign-branch;
    on an int64-accumulate overflow the native raises ``NativeGenomeError`` so the caller falls to
    the exact pure Python path). Byte-identical to the pure Python decision in
    ``genome._gene_expresses``."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_gene_express"):
        raise NativeGenomeError("srmech_genome_gene_express", SRMECH_ERR_NOT_IMPL)
    expressed = ctypes.c_int(0)
    mask_out = ctypes.c_uint64(0)
    rc = LIB.srmech_genome_gene_express(
        _u8(cap), ctypes.c_size_t(leaf_dim), ctypes.c_uint64(cell_state),
        ctypes.byref(expressed), ctypes.byref(mask_out))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_gene_express", rc)
    return bool(expressed.value)


def genome_gene_express_levels_c(cap: bytes, leaf_dim: int, cell_state: int):
    """Native §132 per-gene expression LEVEL — the E3 graded / analog axis (the orthogonal
    companion to :func:`genome_gene_express_c`). ``cap`` is any gene cap leaf (plain ``0x47`` /
    regulatory ``0x67`` / boolean ``0x62`` / threshold ``0x77`` / graded ``0x64``); returns the
    reduced exact-rational LEVEL as a ``(num, den)`` tuple of ints (``den >= 1``). A GRADED gene →
    its clamped reduced dose-response ``Σᵢ level_weightᵢ·bit_i(cell_state) / denom`` in ``[0, 1]``
    (Class-K clamp, Class-I gcd-reduce); a BINARY gene is the degenerate ``{0, 1}`` case →
    ``(1, 1)`` iff its gate passes else ``(0, 1)``. On an int64 dose-accumulate overflow the native
    raises ``NativeGenomeError`` so the caller falls to the exact pure Python (bignum) path.
    Byte-identical to the pure Python decision in ``genome._gene_level``."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_gene_express_levels"):
        raise NativeGenomeError("srmech_genome_gene_express_levels", SRMECH_ERR_NOT_IMPL)
    num = ctypes.c_uint64(0)
    den = ctypes.c_uint64(0)
    rc = LIB.srmech_genome_gene_express_levels(
        _u8(cap), ctypes.c_size_t(leaf_dim), ctypes.c_uint64(cell_state),
        ctypes.byref(num), ctypes.byref(den))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_gene_express_levels", rc)
    return (int(num.value), int(den.value))


def genome_modulator_recover_c(body: bytes, leaf_dim: int, expressed: bytes):
    """Native §133 M1 (the INVERSE of gene_express) — recover the TWO-SIDED cell-state
    FLOOR from an OBSERVED expressed set. ``body`` is the GENE-CAP subset of the strand
    (each gene cap ``leaf_dim`` bytes; the data turns don't gate expression, so the caller
    strips them); ``expressed`` is the observed labels as NUL-delimited UTF-8 tokens
    (``label\\x00label\\x00…``). Returns ``(certain_on, certain_off, undetermined,
    verdict_code)`` — ``certain_on`` = bits every consistent cell_state MUST have set,
    ``certain_off`` = bits it MUST have clear, ``undetermined`` = referenced-but-unpinned
    bits, ``verdict_code`` in {0 UNKNOWN, 1 PARTIAL, 2 EXACT}. SOUND (never over-claims);
    byte-identical to the pure Python ``genome._modulator_recover_pure``."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_modulator_recover"):
        raise NativeGenomeError("srmech_genome_modulator_recover", SRMECH_ERR_NOT_IMPL)
    on = ctypes.c_uint64(0)
    off = ctypes.c_uint64(0)
    und = ctypes.c_uint64(0)
    verdict = ctypes.c_int(0)
    rc = LIB.srmech_genome_modulator_recover(
        _u8(body), ctypes.c_size_t(len(body)), ctypes.c_size_t(leaf_dim),
        _u8(expressed), ctypes.c_size_t(len(expressed)),
        ctypes.byref(on), ctypes.byref(off), ctypes.byref(und), ctypes.byref(verdict))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_modulator_recover", rc)
    return int(on.value), int(off.value), int(und.value), int(verdict.value)


def genome_modulator_consistent_c(body: bytes, leaf_dim: int, expected: bytes,
                                  candidate_cell_state: int) -> bool:
    """Native §133 M2 — forward-CHECK one candidate: is ``set(gene_express(candidate)
    labels) == set(expected)``? ``body`` is the GENE-CAP subset (as for
    :func:`genome_modulator_recover_c`); ``expected`` is the observed labels as
    NUL-delimited UTF-8 tokens. Returns ``True`` iff CONSISTENT (the two label sets are
    equal). ONE-SIDED (CONSISTENT = "could be the state", never "IS the state"). On an
    int64 threshold / graded accumulate OVERFLOW raises ``NativeGenomeError`` so the caller
    falls to the exact pure Python path. Byte-identical to the pure Python set
    comparison."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_modulator_consistent"):
        raise NativeGenomeError("srmech_genome_modulator_consistent", SRMECH_ERR_NOT_IMPL)
    consistent = ctypes.c_int(0)
    rc = LIB.srmech_genome_modulator_consistent(
        _u8(body), ctypes.c_size_t(len(body)), ctypes.c_size_t(leaf_dim),
        _u8(expected), ctypes.c_size_t(len(expected)),
        ctypes.c_uint64(candidate_cell_state), ctypes.byref(consistent))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_modulator_consistent", rc)
    return bool(consistent.value)


def genome_modulator_constraint_c(body: bytes, leaf_dim: int, expressed: bytes) -> bytes:
    """Native §133 M3 — emit the BOOLEAN part (M1 floor + nand / or_terms CLAUSES) of
    the EXACT constraint characterizing the WHOLE consistent-state set, into a caller
    arena, in the canonical big-endian serialization. ``body`` is the GENE-CAP subset
    (as for :func:`genome_modulator_recover_c`); ``expressed`` is the observed labels as
    NUL-delimited UTF-8 tokens. Returns the emitted bytes (byte-identical to the pure
    Python ``genome._serialize_bool_constraint`` of ``_modulator_constraint_bool_pure``).
    The arena is sized to a safe upper bound (20 header + 16 bytes / term, doubled for
    the nand + or emission, + slack). Raises ``NativeGenomeError`` on a non-OK status."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_modulator_constraint"):
        raise NativeGenomeError("srmech_genome_modulator_constraint", SRMECH_ERR_NOT_IMPL)
    # upper bound: every leaf could carry up to (leaf_dim/16) boolean terms; a term is
    # 16 bytes and can appear in BOTH a nand emit and an or emit -> 2x; + header/slack.
    n_caps = len(body) // leaf_dim if leaf_dim else 0
    max_terms = (n_caps * (leaf_dim // 16 + 1))
    cap = 20 + 8 * n_caps + 2 * (16 * max_terms + 4 * n_caps) + 64
    out = (ctypes.c_uint8 * max(cap, 1))()
    out_len = ctypes.c_size_t(0)
    rc = LIB.srmech_genome_modulator_constraint(
        _u8(body), ctypes.c_size_t(len(body)), ctypes.c_size_t(leaf_dim),
        _u8(expressed), ctypes.c_size_t(len(expressed)),
        out, ctypes.c_size_t(cap), ctypes.byref(out_len))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_modulator_constraint", rc)
    return bytes(out[:out_len.value])


def genome_modulator_constraint_satisfies_c(buf: bytes, candidate_cell_state: int) -> bool:
    """Native §133 M3 — does ``candidate_cell_state`` satisfy the BOOLEAN part of an
    emitted constraint ``buf`` (the :func:`genome_modulator_constraint_c` serialization)?
    Returns ``True``/``False`` (byte-identical to the pure Python ``genome._satisfies_bool``).
    The caller ANDs the exact E4/E3 inequality / level checks (the owed-C). Raises
    ``NativeGenomeError`` on a non-OK status."""
    _require_genome()
    if not hasattr(LIB, "srmech_genome_modulator_constraint_satisfies"):
        raise NativeGenomeError("srmech_genome_modulator_constraint_satisfies", SRMECH_ERR_NOT_IMPL)
    satisfied = ctypes.c_int(0)
    rc = LIB.srmech_genome_modulator_constraint_satisfies(
        _u8(buf), ctypes.c_size_t(len(buf)),
        ctypes.c_uint64(candidate_cell_state), ctypes.byref(satisfied))
    if rc != SRMECH_OK:
        raise NativeGenomeError("srmech_genome_modulator_constraint_satisfies", rc)
    return bool(satisfied.value)


